public class HashTable {
    private static final int SIZE = 7; // 소수 선택
    private int[] table;

    public HashTable() {
        table = new int[SIZE];
        java.util.Arrays.fill(table, -1); // -1 = 빈 슬롯
    }

    private int hash(int key) {
        return key % SIZE; // 나눗셈법
    }

    public void insert(int key) {
        int idx = hash(key);
        while (table[idx] != -1) {
            idx = (idx + 1) % SIZE; // 선형 탐사
        }
        table[idx] = key;
    }

    public int search(int key) {
        int start = hash(key), idx = start;
        do {
            if (table[idx] == key) return idx;
            if (table[idx] == -1) return -1;
            idx = (idx + 1) % SIZE;
        } while (idx != start);
        return -1;
    }

    public static void main(String[] args) {
        HashTable ht = new HashTable();
        ht.insert(12); // 12 % 7 = 5
        ht.insert(19); // 19 % 7 = 5 → 충돌 → 6번 슬롯
        ht.insert(5);  //  5 % 7 = 5 → 충돌 → 0번 슬롯
        System.out.println(ht.search(19)); // 6
        System.out.println(ht.search(99)); // -1 (없음)
    }
}
