const SIZE = 7;

class HashTable {
    constructor() {
        this.table = new Array(SIZE).fill(-1);
    }

    hash(key) {
        return key % SIZE;
    }

    insert(key) {
        let idx = this.hash(key);
        while (this.table[idx] !== -1)
            idx = (idx + 1) % SIZE;
        this.table[idx] = key;
    }

    search(key) {
        const start = this.hash(key);
        let idx = start;
        do {
            if (this.table[idx] === key) return idx;
            if (this.table[idx] === -1) return -1;
            idx = (idx + 1) % SIZE;
        } while (idx !== start);
        return -1;
    }
}

const ht = new HashTable();
ht.insert(12); // 12 % 7 = 5
